parameters.jsCode:
// La fila de `comunidad` arranca en cero. Es el tablero de la métrica principal
// del negocio —la tasa de finalización— y A6 la recalcula todos los días.
//
// `fecha_inicio` reemplazó a `grupo` el 2026-08-18. Sin cohortes ya no hay una
// fecha de arranque compartida, así que el día del reto en que va cada alumna
// sólo se puede calcular contra el día en que entró ella.
const v = $('Armar los mensajes').first().json;

return [{
  json: {
    alumna: v.nombre ?? '',
    whatsapp: v.whatsapp ?? '',
    fecha_inicio: new Date().toISOString().slice(0, 10),
    dia_actual: 0,
    ultimo_checkin: '',
    rutinas_completadas: 0,
    estado_riesgo: 'ok',
  },
}];

// Se marca «invitada» y no «sí»: el acceso lo completa ella cuando acepta la
// invitación de Skool. A5 vuelve a escribirle a las 48 h si sigue en este estado.
const v = $('Armar los mensajes').first().json;

return [{
  json: {
    codigo: v.codigo,
    acceso_skool: 'invitada',
  },
}];
